<?php
require_once __DIR__ . '/../functions.php'; requireAdmin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $status = $_POST['status'] ?? 'pending'; if (in_array($status, ['pending', 'paid', 'shipped', 'cancelled'], true)) { $statement = db()->prepare('UPDATE orders SET status = ? WHERE id = ?'); $statement->execute([$status, (int) $_POST['order_id']]); flash('success', 'Order status updated.'); } redirect('orders.php'); }
$orders = db()->query('SELECT o.*, u.name AS user_name, u.email FROM orders o JOIN users u ON u.id = o.user_id ORDER BY o.created_at DESC')->fetchAll();
$title = 'Manage Orders'; require __DIR__ . '/../partials/header.php';
?><div class="section-heading"><h1>Manage orders</h1><a href="index.php">Back to products</a></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>#<?= $order['id'] ?></td><td><?= e($order['user_name']) ?><br><?= e($order['email']) ?></td><td>$<?= number_format((float) $order['total'], 2) ?></td><td><?= e(ucfirst($order['status'])) ?></td><td><form method="post"><input type="hidden" name="order_id" value="<?= $order['id'] ?>"><select name="status"><option>pending</option><option>paid</option><option>shipped</option><option>cancelled</option></select><button>Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__ . '/../partials/footer.php'; ?>
